20	#include "kgzipfilter.h"
21	#include "loggingcategory.h"
22	
23	#include <time.h>
24	
25	#include <zlib.h>
26	#include <QDebug>
27	#include <QIODevice>
28	
29	/* gzip flag byte */
30	#define ORIG_NAME    0x08 /* bit 3 set: original file name present */
31	
32	// #define DEBUG_GZIP
33	
34	class Q_DECL_HIDDEN KGzipFilter::Private
35	{
36	public:
37	    Private()
38	        : headerWritten(false)
39	        , footerWritten(false)
40	        , compressed(false)
41	        , mode(0)
42	        , crc(0)
43	        , isInitialized(false)
44	    {
45	        zStream.zalloc = static_cast<alloc_func>(nullptr);
46	        zStream.zfree = static_cast<free_func>(nullptr);
47	        zStream.opaque = static_cast<voidpf>(nullptr);
48	    }
49	
50	    z_stream zStream;
51	    bool headerWritten;
52	    bool footerWritten;
53	    bool compressed;
54	    int mode;
55	    ulong crc;
56	    bool isInitialized;
57	};
58	
59	KGzipFilter::KGzipFilter()
60	    : d(new Private)
61	{
62	}
63	
64	KGzipFilter::~KGzipFilter()
65	{
66	    delete d;
67	}
68	
69	bool KGzipFilter::init(int mode)
70	{
71	    switch (filterFlags()) {
72	    case NoHeaders:
73	        return init(mode, RawDeflate);
74	    case WithHeaders:
75	        return init(mode, GZipHeader);
76	    case ZlibHeaders:
77	        return init(mode, ZlibHeader);
78	    }
79	    return false;
80	}
81	
82	bool KGzipFilter::init(int mode, Flag flag)
83	{
84	    if (d->isInitialized) {
85	        terminate();
86	    }
87	    d->zStream.next_in = Z_NULL;
88	    d->zStream.avail_in = 0;
89	    if (mode == QIODevice::ReadOnly) {
90	        const int windowBits = (flag == RawDeflate)
91	                               ? -MAX_WBITS /*no zlib header*/
92	                               : (flag == GZipHeader) ?
93	                               MAX_WBITS + 32 /* auto-detect and eat gzip header */
94	                               : MAX_WBITS /*zlib header*/;
95	        const int result = inflateInit2(&d->zStream, windowBits);
96	        if (result != Z_OK) {
97	            //qCDebug(KArchiveLog) << "inflateInit2 returned " << result;
98	            return false;
99	        }
100	    } else if (mode == QIODevice::WriteOnly) {
101	        int result = deflateInit2(&d->zStream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -MAX_WBITS, 8, Z_DEFAULT_STRATEGY); // same here
102	        if (result != Z_OK) {
103	            //qCDebug(KArchiveLog) << "deflateInit returned " << result;
104	            return false;
105	        }
106	    } else {
107	        //qCWarning(KArchiveLog) << "KGzipFilter: Unsupported mode " << mode << ". Only QIODevice::ReadOnly and QIODevice::WriteOnly supported";
108	        return false;
109	    }
110	    d->mode = mode;
111	    d->compressed = true;
112	    d->headerWritten = false;
113	    d->footerWritten = false;
114	    d->isInitialized = true;
115	    return true;
116	}
117	
118	int KGzipFilter::mode() const
119	{
120	    return d->mode;
121	}
122	
123	bool KGzipFilter::terminate()
124	{
125	    if (d->mode == QIODevice::ReadOnly) {
126	        int result = inflateEnd(&d->zStream);
127	        if (result != Z_OK) {
128	            //qCDebug(KArchiveLog) << "inflateEnd returned " << result;
129	            return false;
130	        }
131	    } else if (d->mode == QIODevice::WriteOnly) {
132	        int result = deflateEnd(&d->zStream);
133	        if (result != Z_OK) {
134	            //qCDebug(KArchiveLog) << "deflateEnd returned " << result;
135	            return false;
136	        }
137	    }
138	    d->isInitialized = false;
139	    return true;
140	}
141	
142	void KGzipFilter::reset()
143	{
144	    if (d->mode == QIODevice::ReadOnly) {
145	        int result = inflateReset(&d->zStream);
146	        if (result != Z_OK) {
147	            //qCDebug(KArchiveLog) << "inflateReset returned " << result;
148	            // TODO return false
149	        }
150	    } else if (d->mode == QIODevice::WriteOnly) {
151	        int result = deflateReset(&d->zStream);
152	        if (result != Z_OK) {
153	            //qCDebug(KArchiveLog) << "deflateReset returned " << result;
154	            // TODO return false
155	        }
156	        d->headerWritten = false;
157	        d->footerWritten = false;
158	    }
159	}
160	
161	bool KGzipFilter::readHeader()
162	{
163	    // We now rely on zlib to read the full header (see the MAX_WBITS + 32 in init).
164	    // We just use this method to check if the data is actually compressed.
165	
166	#ifdef DEBUG_GZIP
167	    qCDebug(KArchiveLog) << "avail=" << d->zStream.avail_in;
168	#endif
169	    // Assume not compressed until we see a gzip header
170	    d->compressed = false;
171	    const Bytef *p = d->zStream.next_in;
172	    int i = d->zStream.avail_in;
173	    if ((i -= 10)  < 0) {
174	        return false;    // Need at least 10 bytes
175	    }
176	#ifdef DEBUG_GZIP
177	    qCDebug(KArchiveLog) << "first byte is " << QString::number(*p, 16);
178	#endif
179	    if (*p++ != 0x1f) {
180	        return false;    // GZip magic
181	    }
182	#ifdef DEBUG_GZIP
183	    qCDebug(KArchiveLog) << "second byte is " << QString::number(*p, 16);
184	#endif
185	    if (*p++ != 0x8b) {
186	        return false;
187	    }
188	
189	    d->compressed = true;
190	#ifdef DEBUG_GZIP
191	    qCDebug(KArchiveLog) << "header OK";
192	#endif
193	    return true;
194	}
195	
196	/* Output a 16 bit value, lsb first */
197	#define put_short(w) \
198	    *p++ = uchar((w) & 0xff); \
199	    *p++ = uchar(ushort(w) >> 8);
200	
201	/* Output a 32 bit value to the bit stream, lsb first */
202	#define put_long(n) \
203	    put_short((n) & 0xffff); \
204	    put_short((ulong(n)) >> 16);
205	
206	bool KGzipFilter::writeHeader(const QByteArray &fileName)
207	{
208	    Bytef *p = d->zStream.next_out;
209	    int i = d->zStream.avail_out;
210	    *p++ = 0x1f;
211	    *p++ = 0x8b;
212	    *p++ = Z_DEFLATED;
213	    *p++ = ORIG_NAME;
214	    put_long(time(nullptr));     // Modification time (in unix format)
215	    *p++ = 0; // Extra flags (2=max compress, 4=fastest compress)
216	    *p++ = 3; // Unix
217	
218	    uint len = fileName.length();
219	    for (uint j = 0; j < len; ++j) {
220	        *p++ = fileName[j];
221	    }
222	    *p++ = 0;
223	    int headerSize = p - d->zStream.next_out;
224	    i -= headerSize;
225	    Q_ASSERT(i > 0);
226	    d->crc = crc32(0L, nullptr, 0);
227	    d->zStream.next_out = p;
228	    d->zStream.avail_out = i;
229	    d->headerWritten = true;
230	    return true;
231	}
232	
233	void KGzipFilter::writeFooter()
234	{
235	    Q_ASSERT(d->headerWritten);
236	    Q_ASSERT(!d->footerWritten);
237	    Bytef *p = d->zStream.next_out;
238	    int i = d->zStream.avail_out;
239	    //qCDebug(KArchiveLog) << "avail_out=" << i << "writing CRC=" << QString::number(d->crc, 16) << "at p=" << p;
240	    put_long(d->crc);
241	    //qCDebug(KArchiveLog) << "writing totalin=" << d->zStream.total_in << "at p=" << p;
242	    put_long(d->zStream.total_in);
243	    i -= p - d->zStream.next_out;
244	    d->zStream.next_out = p;
245	    d->zStream.avail_out = i;
246	    d->footerWritten = true;
247	}
248	
249	void KGzipFilter::setOutBuffer(char *data, uint maxlen)
250	{
251	    d->zStream.avail_out = maxlen;
252	    d->zStream.next_out = reinterpret_cast<Bytef *>(data);
253	}
254	void KGzipFilter::setInBuffer(const char *data, uint size)
255	{
256	#ifdef DEBUG_GZIP
257	    qCDebug(KArchiveLog) << "avail_in=" << size;
258	#endif
259	    d->zStream.avail_in = size;
260	    d->zStream.next_in = reinterpret_cast<Bytef *>(const_cast<char *>(data));
261	}
262	int KGzipFilter::inBufferAvailable() const
263	{
264	    return d->zStream.avail_in;
265	}
266	int KGzipFilter::outBufferAvailable() const
267	{
268	    return d->zStream.avail_out;
269	}
270	
271	KGzipFilter::Result KGzipFilter::uncompress_noop()
272	{
273	    // I'm not sure we really need support for that (uncompressed streams),
274	    // but why not, it can't hurt to have it. One case I can think of is someone
275	    // naming a tar file "blah.tar.gz" :-)
276	    if (d->zStream.avail_in > 0) {
277	        int n = (d->zStream.avail_in < d->zStream.avail_out) ? d->zStream.avail_in : d->zStream.avail_out;
278	        memcpy(d->zStream.next_out, d->zStream.next_in, n);
279	        d->zStream.avail_out -= n;
280	        d->zStream.next_in += n;
281	        d->zStream.avail_in -= n;
282	        return KFilterBase::Ok;
283	    } else {
284	        return KFilterBase::End;
285	    }
286	}
287	
288	KGzipFilter::Result KGzipFilter::uncompress()
289	{
290	#ifndef NDEBUG
291	    if (d->mode == 0) {
292	        //qCWarning(KArchiveLog) << "mode==0; KGzipFilter::init was not called!";
293	        return KFilterBase::Error;
294	    } else if (d->mode == QIODevice::WriteOnly) {
295	        //qCWarning(KArchiveLog) << "uncompress called but the filter was opened for writing!";
296	        return KFilterBase::Error;
297	    }
298	    Q_ASSERT(d->mode == QIODevice::ReadOnly);
299	#endif
300	
301	    if (!d->compressed) {
302	        return uncompress_noop();
303	    }
304	
305	#ifdef DEBUG_GZIP
306	    qCDebug(KArchiveLog) << "Calling inflate with avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
307	    qCDebug(KArchiveLog) << "    next_in=" << d->zStream.next_in;
308	#endif
309	
310	    while (d->zStream.avail_in > 0) {
311	        int result = inflate(&d->zStream, Z_SYNC_FLUSH);
312	
313	#ifdef DEBUG_GZIP
314	        qCDebug(KArchiveLog) << " -> inflate returned " << result;
315	        qCDebug(KArchiveLog) << " now avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
316	        qCDebug(KArchiveLog) << "     next_in=" << d->zStream.next_in;
317	#endif
318	
319	        if (result == Z_OK) {
320	            return KFilterBase::Ok;
321	        }
322	
323	        // We can't handle any other results
324	        if (result != Z_STREAM_END) {
325	            return KFilterBase::Error;
326	        }
327	
328	        // It really was the end
329	        if (d->zStream.avail_in == 0) {
330	            return KFilterBase::End;
331	        }
332	
333	        // Store before resetting
334	        Bytef *data = d->zStream.next_in; // This is increased appropriately by zlib beforehand
335	        uInt size = d->zStream.avail_in;
336	
337	        // Reset the stream, if that fails we assume we're at the end
338	        if (!init(d->mode)) {
339	            return KFilterBase::End;
340	        }
341	
342	        // Reset the data to where we left off
343	        d->zStream.next_in = data;
344	        d->zStream.avail_in = size;
345	    }
346	
347	    return KFilterBase::End;
348	}
349	
350	KGzipFilter::Result KGzipFilter::compress(bool finish)
351	{
352	    Q_ASSERT(d->compressed);
353	    Q_ASSERT(d->mode == QIODevice::WriteOnly);
354	
355	    const Bytef *p = d->zStream.next_in;
356	    ulong len = d->zStream.avail_in;
357	#ifdef DEBUG_GZIP
358	    qCDebug(KArchiveLog) << "  calling deflate with avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
359	#endif
360	    const int result = deflate(&d->zStream, finish ? Z_FINISH : Z_NO_FLUSH);
361	    if (result != Z_OK && result != Z_STREAM_END) {
362	        //qCDebug(KArchiveLog) << "  deflate returned " << result;
363	    }
364	    if (d->headerWritten) {
365	        //qCDebug(KArchiveLog) << "Computing CRC for the next " << len - d->zStream.avail_in << " bytes";
366	        d->crc = crc32(d->crc, p, len - d->zStream.avail_in);
367	    }
368	    KGzipFilter::Result callerResult = result == Z_OK ? KFilterBase::Ok : (Z_STREAM_END ? KFilterBase::End : KFilterBase::Error);
369	
370	    if (result == Z_STREAM_END && d->headerWritten && !d->footerWritten) {
371	        if (d->zStream.avail_out >= 8 /*footer size*/) {
372	            //qCDebug(KArchiveLog) << "finished, write footer";
373	            writeFooter();
374	        } else {
375	            // No room to write the footer (#157706/#188415), we'll have to do it on the next pass.
376	            //qCDebug(KArchiveLog) << "finished, but no room for footer yet";
377	            callerResult = KFilterBase::Ok;
378	        }
379	    }
380	    return callerResult;
381	}
