179	void KCompressionDevice::close()
180	{
181	    if (!isOpen()) {
182	        return;
183	    }
184	    if (d->filter->mode() == QIODevice::WriteOnly && d->errorCode == QFileDevice::NoError) {
185	        write(nullptr, 0);    // finish writing
186	    }
187	    //qCDebug(KArchiveLog) << "Calling terminate().";
188	
189	    if (!d->filter->terminate()) {
190	        //qCWarning(KArchiveLog) << "KCompressionDevice::close: terminate returned an error";
191	        d->errorCode = QFileDevice::UnspecifiedError;
192	    }
193	    if (d->bOpenedUnderlyingDevice) {
194	        QIODevice *dev = d->filter->device();
195	        dev->close();
196	        d->propagateErrorCode();
197	    }
198	    setOpenMode(QIODevice::NotOpen);
