254	bool KCompressionDevice::atEnd() const
255	{
256	    return (d->type == KCompressionDevice::None || d->result == KFilterBase::End)
257	           && QIODevice::atEnd() // take QIODevice's internal buffer into account
258	           && d->filter->device()->atEnd();
259	}
260	
261	qint64 KCompressionDevice::readData(char *data, qint64 maxlen)
262	{
263	    Q_ASSERT(d->filter->mode() == QIODevice::ReadOnly);
264	    //qCDebug(KArchiveLog) << "maxlen=" << maxlen;
265	    KFilterBase *filter = d->filter;
266	
267	    uint dataReceived = 0;
268	
269	    // We came to the end of the stream
270	    if (d->result == KFilterBase::End) {
271	        return dataReceived;
272	    }
273	
274	    // If we had an error, return -1.
275	    if (d->result != KFilterBase::Ok) {
276	        return -1;
277	    }
278	
279	    qint64 availOut = maxlen;
280	    filter->setOutBuffer(data, maxlen);
281	
282	    while (dataReceived < maxlen) {
283	        if (filter->inBufferEmpty()) {
284	            // Not sure about the best size to set there.
285	            // For sure, it should be bigger than the header size (see comment in readHeader)
286	            d->buffer.resize(BUFFER_SIZE);
287	            // Request data from underlying device
288	            int size = filter->device()->read(d->buffer.data(),
289	                                              d->buffer.size());
290	            //qCDebug(KArchiveLog) << "got" << size << "bytes from device";
291	            if (size) {
292	                filter->setInBuffer(d->buffer.data(), size);
293	            } else {
294	                // Not enough data available in underlying device for now
295	                break;
296	            }
297	        }
298	        if (d->bNeedHeader) {
299	            (void) filter->readHeader();
300	            d->bNeedHeader = false;
301	        }
302	
303	        d->result = filter->uncompress();
304	
305	        if (d->result == KFilterBase::Error) {
306	            //qCWarning(KArchiveLog) << "KCompressionDevice: Error when uncompressing data";
307	            break;
308	        }
309	
310	        // We got that much data since the last time we went here
311	        uint outReceived = availOut - filter->outBufferAvailable();
312	        //qCDebug(KArchiveLog) << "avail_out = " << filter->outBufferAvailable() << " result=" << d->result << " outReceived=" << outReceived;
313	        if (availOut < uint(filter->outBufferAvailable())) {
314	            //qCWarning(KArchiveLog) << " last availOut " << availOut << " smaller than new avail_out=" << filter->outBufferAvailable() << " !";
315	        }
316	
317	        dataReceived += outReceived;
318	        data += outReceived;
319	        availOut = maxlen - dataReceived;
320	        if (d->result == KFilterBase::End) {
321	            // We're actually at the end, no more data to check
322	            if (filter->device()->atEnd()) {
323	                break;
324	            }
325	
326	            // Still not done, re-init and try again
327	            filter->init(filter->mode());
328	        }
329	        filter->setOutBuffer(data, availOut);
330	    }
331	
332	    d->deviceReadPos += dataReceived;
333	    return dataReceived;
334	}
335	
336	qint64 KCompressionDevice::writeData(const char *data /*0 to finish*/, qint64 len)
337	{
338	    KFilterBase *filter = d->filter;
339	    Q_ASSERT(filter->mode() == QIODevice::WriteOnly);
340	    // If we had an error, return 0.
341	    if (d->result != KFilterBase::Ok) {
342	        return 0;
343	    }
344	
345	    bool finish = (data == nullptr);
346	    if (!finish) {
347	        filter->setInBuffer(data, len);
348	        if (d->bNeedHeader) {
349	            (void)filter->writeHeader(d->origFileName);
350	            d->bNeedHeader = false;
351	        }
352	    }
353	
354	    uint dataWritten = 0;
355	    uint availIn = len;
356	    while (dataWritten < len || finish) {
357	
358	        d->result = filter->compress(finish);
359	
360	        if (d->result == KFilterBase::Error) {
361	            //qCWarning(KArchiveLog) << "KCompressionDevice: Error when compressing data";
362	            // What to do ?
363	            break;
364	        }
365	
366	        // Wrote everything ?
367	        if (filter->inBufferEmpty() || (d->result == KFilterBase::End)) {
368	            // We got that much data since the last time we went here
369	            uint wrote = availIn - filter->inBufferAvailable();
370	
371	            //qCDebug(KArchiveLog) << " Wrote everything for now. avail_in=" << filter->inBufferAvailable() << "result=" << d->result << "wrote=" << wrote;
372	
373	            // Move on in the input buffer
374	            data += wrote;
375	            dataWritten += wrote;
376	
377	            availIn = len - dataWritten;
378	            //qCDebug(KArchiveLog) << " availIn=" << availIn << "dataWritten=" << dataWritten << "pos=" << pos();
379	            if (availIn > 0) {
380	                filter->setInBuffer(data, availIn);
381	            }
382	        }
383	
384	        if (filter->outBufferFull() || (d->result == KFilterBase::End) || finish) {
385	            //qCDebug(KArchiveLog) << " writing to underlying. avail_out=" << filter->outBufferAvailable();
386	            int towrite = d->buffer.size() - filter->outBufferAvailable();
387	            if (towrite > 0) {
388	                // Write compressed data to underlying device
389	                int size = filter->device()->write(d->buffer.data(), towrite);
390	                if (size != towrite) {
391	                    //qCWarning(KArchiveLog) << "KCompressionDevice::write. Could only write " << size << " out of " << towrite << " bytes";
392	                    d->errorCode = QFileDevice::WriteError;
393	                    setErrorString(tr("Could not write. Partition full?"));
394	                    return 0; // indicate an error
395	                }
396	                //qCDebug(KArchiveLog) << " wrote " << size << " bytes";
397	            }
398	            if (d->result == KFilterBase::End) {
399	                Q_ASSERT(finish); // hopefully we don't get end before finishing
400	                break;
401	            }
402	            d->buffer.resize(BUFFER_SIZE);
403	            filter->setOutBuffer(d->buffer.data(), d->buffer.size());
404	        }
405	    }
406	
407	    return dataWritten;
408	}
409	
410	void KCompressionDevice::setOrigFileName(const QByteArray &fileName)
411	{
412	    d->origFileName = fileName;
413	}
414	
415	void KCompressionDevice::setSkipHeaders()
416	{
417	    d->bSkipHeaders = true;
418	}
419	
420	KFilterBase *KCompressionDevice::filterBase()
421	{
422	    return d->filter;
423	}
